use codeint_model::language::SourceSet;

#[cfg(test)]
mod tests;

const TEST_FOLDERS: [&str; 3] = ["tests", "benches", "examples"];

const GENERATED_MARKERS: [&str; 6] = [
    "@generated",
    "auto-generated",
    "autogenerated",
    "automatically generated",
    "do not edit",
    "generated by",
];

pub(crate) fn classify(path: &str, text: &str) -> SourceSet {
    if has_generated_header(text) {
        return SourceSet::Generated;
    }
    if is_test_path(path) {
        return SourceSet::Test;
    }
    SourceSet::Production
}

fn is_test_path(path: &str) -> bool {
    let mut segments = path.split('/').peekable();
    let mut file_name = "";
    while let Some(segment) = segments.next() {
        if segments.peek().is_some() {
            if TEST_FOLDERS.contains(&segment) {
                return true;
            }
        } else {
            file_name = segment;
        }
    }
    file_name == "tests.rs" || file_name.ends_with("_test.rs") || file_name.ends_with("_tests.rs")
}

fn has_generated_header(text: &str) -> bool {
    let header = leading_comment_block(text);
    let lower = header.to_ascii_lowercase();
    GENERATED_MARKERS
        .iter()
        .any(|marker| lower.contains(marker))
}

fn leading_comment_block(text: &str) -> String {
    let bytes = text.as_bytes();
    let mut index = if bytes.starts_with(&[0xEF, 0xBB, 0xBF]) {
        3
    } else {
        0
    };
    let mut comments = String::new();
    while index < bytes.len() {
        while index < bytes.len() && bytes[index].is_ascii_whitespace() {
            index += 1;
        }
        if bytes[index..].starts_with(b"//") {
            let start = index;
            while index < bytes.len() && bytes[index] != b'\n' {
                index += 1;
            }
            comments.push_str(&text[start..index]);
            comments.push('\n');
        } else if bytes[index..].starts_with(b"/*") {
            let start = index;
            index += 2;
            let mut depth = 1usize;
            while index < bytes.len() && depth > 0 {
                if bytes[index..].starts_with(b"/*") {
                    depth += 1;
                    index += 2;
                } else if bytes[index..].starts_with(b"*/") {
                    depth -= 1;
                    index += 2;
                } else {
                    index += 1;
                }
            }
            comments.push_str(&text[start..index]);
            comments.push('\n');
        } else {
            break;
        }
    }
    comments
}
